SINA_SMART["anat2-small-intestine"] = {"lecture":"anat2-small-intestine","title":"The small intestine","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-small-intestine:e0","text":"Small intestine: 6-7 m, pylorus → ileocaecal junction; digestion, absorption, motility.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-small-intestine:e2","text":"Plicae, villi, microvilli increase surface.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-small-intestine:e3","text":"Cells: enterocytes, goblet, Paneth, enteroendocrine.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-small-intestine:e4","text":"Duodenum: C-shaped, mostly retroperitoneal, 4 parts.","topic":"Duodenum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-small-intestine:e5","text":"Major papilla in D2; SMA crosses D3; ligament of Treitz at D4.","topic":"Duodenum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-small-intestine:e6","text":"Duodenum supply: coeliac + SMA (pancreaticoduodenal).","topic":"Duodenum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-small-intestine:e1","text":"Duodenum 20-30 cm, jejunum ~2.5 m (2/5), ileum ~3.5 m (3/5).","topic":"Jejunum, ileum and mesentery","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-small-intestine:e7","text":"Brunner's glands (duodenum); Peyer's patches (ileum).","topic":"Jejunum, ileum and mesentery","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-small-intestine:e8","text":"Jejunum/ileum intraperitoneal on a mesentery.","topic":"Jejunum, ileum and mesentery","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-small-intestine:e9","text":"SMA gives 15-18 branches → arcades → vasa recta.","topic":"Jejunum, ileum and mesentery","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"q7l0pw":"a","1nzy6eh":"a","mj7ll0":"a","1793rxb":"a","m16ls2":"a","18rlewa":"a","ixkojr":"a","1i3ll57":"a","gkvjrw":"a","7d5ou0":"a","1nuhnx2":"a","1k0p0u3":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-small-intestine:e0":{"s":0,"u":["Small intestine: 6-7 m, pylorus → ileocaecal junction; digestion, absorption, motility.","The small intestine is the longest part of the GI tract (about 6-7 m ), filling most of the abdomen from the pylorus to the ileocaecal junction .","Its roles are digestion, absorption and motility ."],"dp":[]},"anat2-small-intestine:e2":{"s":0,"u":["Plicae, villi, microvilli increase surface.","Surface area is multiplied by plicae circulares , villi and microvilli ."],"dp":[]},"anat2-small-intestine:e3":{"s":0,"u":["Cells: enterocytes, goblet, Paneth, enteroendocrine.","Wall: mucosa, submucosa, muscularis externa, serosa; special cells: enterocytes , goblet cells , Paneth cells (antimicrobial) and enteroendocrine cells."],"dp":[]},"anat2-small-intestine:e4":{"s":1,"u":["Duodenum: C-shaped, mostly retroperitoneal, 4 parts.","C-shaped , 20-25 cm, curving around the head of the pancreas; mostly retroperitoneal (except its first part), the site of chemical digestion : gastric chyme is neutralised and mixed with bile and pancreatic juice ."],"dp":[]},"anat2-small-intestine:e5":{"s":1,"u":["Major papilla in D2; SMA crosses D3; ligament of Treitz at D4.","Four parts: 1st (superior) , with the mobile, intraperitoneal duodenal cap; 2nd (descending) , receiving the bile and pancreatic ducts at the major duodenal papilla ; 3rd (horizontal) , crossed in front by the superior mesenteric vessels ; 4th (ascending) , ending at the duodenojejunal flexure , held by the ligament of Treitz (suspensory ligament of the duodenum)."],"dp":[{"h":"Why the SMA can squeeze the duodenum","t":"The third part of the duodenum crosses the spine in the angle between the aorta behind and the superior mesenteric artery in front. Normally a fat pad keeps this angle open. After major weight loss the angle narrows and the artery can compress the duodenum (superior mesenteric artery syndrome), causing vomiting after meals. The same relationship explains why the D3 region matters in trauma and surgery. Source: the lecture's duodenum description."},{"h":"Note","t":"Duodenum : 4 parts; only D1 (cap) is intraperitoneal , the rest retroperitoneal. D2 = major papilla (bile + pancreatic ducts); D3 crossed by the SMA/SMV ; D4 → duodenojejunal flexure ( ligament of Treitz )."},{"h":"Clinical","t":"The ligament of Treitz divides upper from lower GI bleeding. The terminal ileum absorbs B12 and bile salts: resection or Crohn's disease there → B12 deficiency and fat malabsorption."}]},"anat2-small-intestine:e6":{"s":1,"u":["Duodenum supply: coeliac + SMA (pancreaticoduodenal).","Its blood supply comes from the coeliac trunk (superior pancreaticoduodenal arteries via the gastroduodenal) and the SMA (inferior pancreaticoduodenal arteries), reflecting the foregut-midgut junction."],"dp":[{"h":"Note","t":"The major papilla marks the foregut/midgut junction : above it supply is coeliac (superior pancreaticoduodenal via GDA), below it SMA (inferior pancreaticoduodenal)."}]},"anat2-small-intestine:e1":{"s":2,"u":["Duodenum 20-30 cm, jejunum ~2.5 m (2/5), ileum ~3.5 m (3/5).","The jejunum is wider, thicker and more vascular, with tall plicae; the ileum is narrower, with Peyer's patches , and ends at the ileocaecal junction .","Arteries : 15-18 jejunal and ileal branches of the SMA form anastomotic loops ( arcades ) that give straight vasa recta to the wall (long with few arcades in the jejunum; short with many arcades in the ileum)."],"dp":[{"h":"Note","t":"Jejunum vs ileum : jejunum = wider, thicker, redder, tall plicae, long vasa recta, few arcades ; ileum = narrower, Peyer's patches , short vasa recta, many arcades , more mesenteric fat."}]},"anat2-small-intestine:e7":{"s":2,"u":["Brunner's glands (duodenum); Peyer's patches (ileum).","The jejunum is wider, thicker and more vascular, with tall plicae; the ileum is narrower, with Peyer's patches , and ends at the ileocaecal junction ."],"dp":[{"h":"Note","t":"Glands: Brunner's (submucosa of the duodenum , alkaline mucus); Paneth cells (crypts, antimicrobial); Peyer's patches ( ileum ). Lengths: duodenum 25 cm, jejunum 2/5, ileum 3/5 of the rest."}]},"anat2-small-intestine:e8":{"s":2,"u":["Jejunum/ileum intraperitoneal on a mesentery.","Both are intraperitoneal , suspended by the mesentery , whose root runs obliquely on the posterior wall and carries the vessels, nerves and lymphatics.","The jejunum is wider, thicker and more vascular, with tall plicae; the ileum is narrower, with Peyer's patches , and ends at the ileocaecal junction ."],"dp":[]},"anat2-small-intestine:e9":{"s":2,"u":["SMA gives 15-18 branches → arcades → vasa recta.","Arteries : 15-18 jejunal and ileal branches of the SMA form anastomotic loops ( arcades ) that give straight vasa recta to the wall (long with few arcades in the jejunum; short with many arcades in the ileum)."],"dp":[]}},"meta":{"q7l0pw":{"a":"recall","vg":"anat2-small-intestine:e0/recall/1"},"1nzy6eh":{"a":"recall","vg":"anat2-small-intestine:e7/recall/1"},"mj7ll0":{"a":"recall","vg":"anat2-small-intestine:e4/recall/1"},"1793rxb":{"a":"recall","vg":"anat2-small-intestine:e4/recall/2"},"m16ls2":{"a":"recall","vg":"anat2-small-intestine:e5/recall/1"},"18rlewa":{"a":"recall","vg":"anat2-small-intestine:e5/recall/2"},"ixkojr":{"a":"recall","vg":"anat2-small-intestine:e7/recall/2"},"1i3ll57":{"a":"recall","vg":"anat2-small-intestine:e7/recall/3"},"gkvjrw":{"a":"relationship","vg":"anat2-small-intestine:e7/relationship/1"},"7d5ou0":{"a":"recall","vg":"anat2-small-intestine:e1/recall/1"},"1nuhnx2":{"a":"recall","vg":"anat2-small-intestine:e9/recall/1"},"1k0p0u3":{"a":"recall","vg":"anat2-small-intestine:e3/recall/1"}},"explRev":"82d0a13bba7c"};
